package org.beyondlight;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import java.io.*;import java.util.regex.*;
/** JSONL local registry; raw equation text/source strings are kept unchanged. */
public final class EquationRegistry {
 public record Equation(String id,String name,String lhs,String rhs,String variables,String discipline,String source,String author,String publicationYear,String url,String assumptions,String status,String created){}
 private final Path path;
 public EquationRegistry(Path path){this.path=path;}
 public synchronized List<Equation> all(){try{if(!Files.exists(path))return new ArrayList<>();List<Equation> out=new ArrayList<>();for(String l:Files.readAllLines(path))if(!l.isBlank())out.add(read(l));return out;}catch(IOException e){throw new IllegalStateException("registry read failed: "+e.getMessage());}}
 public synchronized Equation add(String name,String equation,String variables,String discipline,String source,String url,String assumptions){return add(name,equation,variables,discipline,source,"","",url,assumptions);}
 public synchronized Equation add(String name,String equation,String variables,String discipline,String source,String author,String publicationYear,String url,String assumptions){if(name.isBlank())throw new IllegalArgumentException("equation name is required");String[] sides=equation.split("=(?!=)",2);if(sides.length!=2)throw new IllegalArgumentException("equation must contain one = sign");Symbolic.parse(sides[0]);Symbolic.parse(sides[1]);String st=source.isBlank()||url.isBlank()?"UNVERIFIED — INCOMPLETE SOURCE":"UNVERIFIED — SOURCE PROVIDED";Equation e=new Equation(UUID.randomUUID().toString(),name,sides[0].trim(),sides[1].trim(),variables,discipline,source,author,publicationYear,url,assumptions,st,Instant.now().toString());try{Files.createDirectories(path.getParent());Files.writeString(path,json(e)+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.APPEND);return e;}catch(IOException ex){throw new IllegalStateException("registry save failed: "+ex.getMessage());}}
 public synchronized void delete(String id){List<Equation> es=all();if(!es.removeIf(e->e.id.equals(id)))throw new IllegalArgumentException("equation not found");try{Files.write(path,es.stream().map(EquationRegistry::json).toList(),StandardCharsets.UTF_8);}catch(IOException ex){throw new IllegalStateException("registry update failed: "+ex.getMessage());}}
 public synchronized Equation update(String id,String name,String equation,String variables,String discipline,String source,String url,String assumptions){Equation old=all().stream().filter(e->e.id.equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("equation not found"));return update(id,name,equation,variables,discipline,source,old.author,old.publicationYear,url,assumptions);}
 public synchronized Equation update(String id,String name,String equation,String variables,String discipline,String source,String author,String publicationYear,String url,String assumptions){List<Equation> es=all();Equation old=es.stream().filter(e->e.id.equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("equation not found"));String[] sides=equation.split("=(?!=)",2);if(sides.length!=2)throw new IllegalArgumentException("equation must contain one = sign");Symbolic.parse(sides[0]);Symbolic.parse(sides[1]);String st=source.isBlank()||url.isBlank()?"UNVERIFIED — INCOMPLETE SOURCE":"UNVERIFIED — SOURCE PROVIDED";Equation e=new Equation(id,name,sides[0].trim(),sides[1].trim(),variables,discipline,source,author,publicationYear,url,assumptions,st,old.created);es.removeIf(x->x.id.equals(id));es.add(e);try{Files.write(path,es.stream().map(EquationRegistry::json).toList(),StandardCharsets.UTF_8);}catch(IOException ex){throw new IllegalStateException("registry update failed");}return e;}
 public synchronized int importJson(String input){Matcher m=Pattern.compile("\\{[^{}]*\\}").matcher(input);int count=0;while(m.find()){String j=m.group();String eq=field(j,"lhs")+" = "+field(j,"rhs");add(field(j,"name"),eq,field(j,"variables"),field(j,"discipline"),field(j,"source"),field(j,"author"),field(j,"publication_year"),field(j,"url"),field(j,"assumptions"));count++;}if(count==0)throw new IllegalArgumentException("no equation objects found in JSON input");return count;}
 public List<Equation> search(String q){String t=q.toLowerCase();return all().stream().filter(e->(e.name+e.lhs+e.rhs+e.discipline+e.source).toLowerCase().contains(t)).toList();}
 public static String json(Equation e){return "{\"id\":"+q(e.id)+",\"name\":"+q(e.name)+",\"lhs\":"+q(e.lhs)+",\"rhs\":"+q(e.rhs)+",\"variables\":"+q(e.variables)+",\"discipline\":"+q(e.discipline)+",\"source\":"+q(e.source)+",\"author\":"+q(e.author)+",\"publication_year\":"+q(e.publicationYear)+",\"url\":"+q(e.url)+",\"assumptions\":"+q(e.assumptions)+",\"status\":"+q(e.status)+",\"created\":"+q(e.created)+"}";}
 private static String q(String s){return "\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n")+"\"";}
 private static Equation read(String s){return new Equation(field(s,"id"),field(s,"name"),field(s,"lhs"),field(s,"rhs"),field(s,"variables"),field(s,"discipline"),field(s,"source"),field(s,"author"),field(s,"publication_year"),field(s,"url"),field(s,"assumptions"),field(s,"status"),field(s,"created"));}
 private static String field(String j,String key){Matcher m=Pattern.compile("\\\""+key+"\\\"\\s*:\\s*\\\"((?:\\\\.|[^\\\"])*)\\\"").matcher(j);if(!m.find())return "";return m.group(1).replace("\\n","\n").replace("\\\"","\"").replace("\\\\","\\");}
 public static Map<String,Dimensions.D> dimensions(String input){Map<String,Dimensions.D> m=new LinkedHashMap<>();for(String p:input.split(",")){if(p.isBlank())continue;String[]a=p.trim().split(":",2);if(a.length!=2)throw new IllegalArgumentException("variables must be name:dimension pairs separated by commas");m.put(a[0].trim(),Dimensions.parse(a[1].trim()));}return m;}
}
